CREATE FUNCTION operations.guard_workflow_definition() RETURNS trigger LANGUAGE plpgsql VOLATILE AS $$
BEGIN
 IF current_setting('transaction_isolation') <> 'read committed' THEN
  RAISE EXCEPTION 'WORKFLOW_DEFINITION_REQUIRES_READ_COMMITTED' USING ERRCODE='23514';
 END IF;
 PERFORM 1 FROM operations.workflow_version WHERE business_id=NEW.business_id AND id=NEW.workflow_version_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'WORKFLOW_VERSION_SCOPE_MISMATCH' USING ERRCODE='23503'; END IF;
 IF EXISTS(SELECT 1 FROM operations.workflow_definition_seal WHERE workflow_version_id=NEW.workflow_version_id) THEN
  RAISE EXCEPTION 'WORKFLOW_DEFINITION_SEALED' USING ERRCODE='23514';
 END IF;
 IF TG_TABLE_NAME='workflow_definition_seal' THEN
  IF NOT EXISTS(SELECT 1 FROM operations.workflow_definition WHERE workflow_version_id=NEW.workflow_version_id)
   OR NOT EXISTS(SELECT 1 FROM operations.workflow_step WHERE workflow_version_id=NEW.workflow_version_id) THEN
   RAISE EXCEPTION 'WORKFLOW_DEFINITION_INCOMPLETE' USING ERRCODE='23514';
  END IF;
  IF EXISTS(
   WITH RECURSIVE paths(origin,target) AS (
    SELECT step_number,depends_on_step FROM operations.workflow_step_dependency WHERE workflow_version_id=NEW.workflow_version_id
    UNION
    SELECT p.origin,d.depends_on_step FROM paths p JOIN operations.workflow_step_dependency d
     ON d.workflow_version_id=NEW.workflow_version_id AND d.step_number=p.target
   ) SELECT 1 FROM paths WHERE origin=target
  ) THEN RAISE EXCEPTION 'WORKFLOW_DEFINITION_CYCLE' USING ERRCODE='23514'; END IF;
  NEW.created_at:=clock_timestamp(); NEW.created_by:=current_user;
 END IF;
 RETURN NEW;
END $$
